//! Minimal ldk-node wrapper for smite fuzzing.
//!
//! Uses bitcoind RPC as the backend, prints the node's pubkey on startup, and
//! serves target commands as JSON-RPC over a Unix socket until a `stop`
//! request shuts it down cleanly. Ignores all events generated by ldk-node
//! since we reset the VM after each fuzz iteration anyway.

use std::io::{BufReader, Write};
use std::net::SocketAddr;
use std::os::unix::net::{UnixListener, UnixStream};
use std::time::Duration;

use ldk_node::Builder;
use ldk_node::bitcoin::Network;
use ldk_node::lightning_invoice::{Bolt11InvoiceDescription, Description};
use serde::Deserialize;
use serde_json::{Value, json};

/// Path prefix the crash handler reads panic reports from.
const PANIC_LOG_PATH: &str = "/tmp/smite-panic.log";

/// Stores the panic message where the `LD_PRELOADed` crash handler can retrieve
/// it. With `panic = "abort"`, panics only reach stderr, which scenario/Nyx
/// discards, so this allows crash reports to include the panic message and its
/// source location.
fn install_panic_hook() {
    let path = format!("{PANIC_LOG_PATH}.{}", std::process::id());
    let default_hook = std::panic::take_hook();

    std::panic::set_hook(Box::new(move |info| {
        // Renders as "panicked at <file>:<line>:<col>:\n<message>".
        let _ = std::fs::write(&path, format!("{info}\n"));
        default_hook(info);
    }));
}

/// JSON-RPC methods the wrapper serves, named in `snake_case` (e.g.
/// `sync_wallets`). Unknown methods fail to parse.
#[derive(Deserialize)]
#[serde(rename_all = "snake_case")]
enum Method {
    SyncWallets,
    ReceiveVariableAmount,
    Stop,
}

/// A JSON-RPC request. `jsonrpc` and `params` are unused.
#[derive(Deserialize)]
struct RpcRequest {
    id: Value,
    method: Method,
}

/// Writes the JSON-RPC response to request `id`, with either `result` or
/// `error`, to `stream`.
fn respond(stream: &mut UnixStream, id: &Value, result: Result<Value, String>) {
    let response = match result {
        Ok(result) => json!({ "jsonrpc": "2.0", "id": id, "result": result }),
        // `code` is omitted, since `message` alone describes the error.
        Err(message) => json!({ "jsonrpc": "2.0", "id": id, "error": { "message": message } }),
    };
    let _ = stream.write_all(&serde_json::to_vec(&response).expect("serializable response"));
}

fn main() {
    install_panic_hook();

    let args: Vec<String> = std::env::args().collect();
    if args.len() != 6 {
        eprintln!(
            "Usage: {} <data-dir> <listen-port> <bitcoind-rpc-port> <target-blockheight> <rpc-socket>",
            args[0]
        );
        std::process::exit(1);
    }

    let data_dir = args[1].clone();
    let listen_port: u16 = args[2].parse().expect("valid listen port");
    let rpc_port: u16 = args[3].parse().expect("valid RPC port");
    let target_blockheight: u32 = args[4].parse().expect("valid target blockheight");
    let rpc_socket = &args[5];

    let listen_addr: SocketAddr = format!("0.0.0.0:{listen_port}")
        .parse()
        .expect("valid listen address");

    let node = Builder::new()
        .set_network(Network::Regtest)
        .set_chain_source_bitcoind_rpc(
            "127.0.0.1".to_string(),
            rpc_port,
            "rpcuser".to_string(),
            "rpcpass".to_string(),
        )
        .set_listening_addresses(vec![listen_addr.into()])
        .expect("valid listening addresses")
        // ldk-node only accepts announced channels once both an alias and
        // listening addresses are set, and rejects them otherwise.
        .set_node_alias("smite-ldk".to_string())
        .expect("valid node alias")
        .set_storage_dir_path(data_dir)
        .build()
        .expect("node build");

    node.start().expect("node start");

    // Wait for the chain to sync to the target blockheight before signaling
    // readiness. ldk-node polls bitcoind every 2 seconds, so this can take a
    // few seconds after startup.
    while node.status().current_best_block.height < target_blockheight {
        std::thread::sleep(Duration::from_secs(1));
    }

    // Output for LdkTarget to parse. LdkTarget funds ADDRESS, and READY
    // follows once the funds confirm, so the node can fee-bump, sweep, and
    // accept inbound anchor channels, which require an on-chain reserve.
    println!("PUBKEY:{}", node.node_id());
    let address = node
        .onchain_payment()
        .new_address()
        .expect("new on-chain address");
    println!("ADDRESS:{address}");
    while node.list_balances().spendable_onchain_balance_sats == 0 {
        std::thread::sleep(Duration::from_secs(1));
    }

    // Bind before READY, so the socket accepts RPCs once READY is printed.
    let listener = UnixListener::bind(rpc_socket).expect("RPC socket bind");

    println!("READY");

    // Serve JSON-RPC requests, one per connection, until a `stop` request is
    // answered. Connections are served one at a time with no read timeout, so
    // a connection that sends no request blocks the ones queued behind it.
    for mut stream in listener.incoming().flatten() {
        let request = match serde_json::Deserializer::from_reader(BufReader::new(&stream))
            .into_iter::<RpcRequest>()
            .next()
        {
            Some(Ok(request)) => request,
            // Also covers unknown methods, which serde reports by name along
            // with the served ones. A request that fails to parse has no
            // readable id, so the error is answered with a null one.
            Some(Err(e)) => {
                respond(&mut stream, &Value::Null, Err(e.to_string()));
                continue;
            }
            None => continue,
        };

        match request.method {
            // Sync the wallet on request. ldk-node's own 2s background poll
            // keeps running, so this is technically redundant and may race it,
            // but that's safe: ldk-node coalesces concurrent syncs, so whichever
            // loses the race just waits on the in-flight sync's result rather
            // than applying the block twice. We accept the redundancy to sync on
            // demand instead of up to 2s later.
            //
            // A failed sync is only logged, as ldk-node's own background poll
            // does: it can't be caused by the request, only by bitcoind or the
            // data dir being unavailable, or by the node shutting down.
            Method::SyncWallets => {
                if let Err(e) = node.sync_wallets() {
                    eprintln!("sync_wallets failed: {e}");
                }
                respond(&mut stream, &request.id, Ok(json!({})));
            }
            // Creates an any-amount invoice valid for an hour.
            Method::ReceiveVariableAmount => {
                let result = node
                    .bolt11_payment()
                    .receive_variable_amount(
                        &Bolt11InvoiceDescription::Direct(Description::empty()),
                        3600,
                    )
                    .map(|invoice| json!({ "bolt11": invoice.to_string() }))
                    .map_err(|e| e.to_string());
                respond(&mut stream, &request.id, result);
            }
            // Shut down on request. Reply first, then stop serving so the node
            // is stopped below.
            Method::Stop => {
                respond(&mut stream, &request.id, Ok(json!({})));
                break;
            }
        }
    }

    node.stop().expect("node stop");
}
